import subprocess
import sys

def run_text_utility(executable: str, arguments: list[str]) -> str:
    if executable not in ("/usr/bin/printf", "/bin/echo"):
        raise ValueError("Executable is disallowed")
    return subprocess.run(
        [executable] + arguments,
        capture_output=True,
        text=True,
        check=True,
    ).stdout
